-- Database di RicordaMi (SQLite: Cloudflare D1 oggi, un server tuo domani).
CREATE TABLE IF NOT EXISTS utenti (id TEXT PRIMARY KEY, nome TEXT NOT NULL, creato INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS gettoni (hash TEXT PRIMARY KEY, utente TEXT NOT NULL, creato INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS gruppi (id TEXT PRIMARY KEY, nome TEXT NOT NULL, creatore TEXT NOT NULL, creato INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS membri (gruppo TEXT NOT NULL, utente TEXT NOT NULL, nome TEXT NOT NULL, colore TEXT NOT NULL, entrato INTEGER NOT NULL, PRIMARY KEY (gruppo, utente));
CREATE INDEX IF NOT EXISTS membri_utente ON membri(utente);
CREATE TABLE IF NOT EXISTS inviti (codice TEXT PRIMARY KEY, gruppo TEXT NOT NULL, da TEXT NOT NULL, scade INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS voci (id TEXT PRIMARY KEY, gruppo TEXT NOT NULL, autore TEXT NOT NULL, dati TEXT NOT NULL, seq INTEGER NOT NULL, eliminata INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS voci_seq ON voci(gruppo, seq);
CREATE TABLE IF NOT EXISTS eventi (seq INTEGER PRIMARY KEY, gruppo TEXT NOT NULL, voce TEXT, tipo TEXT NOT NULL, da TEXT NOT NULL, per TEXT NOT NULL, titolo TEXT, testo TEXT, creato INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS eventi_gruppo ON eventi(gruppo, seq);
CREATE TABLE IF NOT EXISTS contatore (id INTEGER PRIMARY KEY CHECK (id = 1), n INTEGER NOT NULL);
INSERT OR IGNORE INTO contatore (id, n) VALUES (1, 0);
CREATE TABLE IF NOT EXISTS dispositivi (token TEXT PRIMARY KEY, utente TEXT NOT NULL, piattaforma TEXT NOT NULL, agg INTEGER NOT NULL);
